LAYOUT.write_text('// GENERATED by tests/record_native_app_unit634_2008.py: sizeof probes (mov eax, imm32; ret).\n'
                  '#include "v8datamodel/Value.h"\n' +
                  ''.join('unsigned nativeAppUnit634%sSize() { return sizeof(RBX::%s); }\n' % (t[0], t[0]) for t in TYPES) +
                  '')
layout_obj, layout_flags = build('NativeAppUnit634ValueLayout', LAYOUT)
sizes = {}
for n, b, _ in match.coff_functions(layout_obj.read_bytes()):
    m = re.match(r'\?nativeAppUnit634(\w+)Size@@', n)
    if m:
        assert b[:1] == b'\xb8' and b[5:] == b'\xc3', (n, b.hex())
        sizes[m.group(1)] = struct.unpack_from('<I', b, 1)[0]
for name, _, _, create, ctor, size in TYPES:
    assert sizes[name] == size, (name, hex(sizes[name]), hex(size))
    body, _, _ = match.target('2008-06', '%08x' % create)
    i = body.index(b'\x68' + struct.pack('<I', size))
    call = body.index(b'\xe8', i + 5)
    while (create + call + 5 + struct.unpack_from('<i', body, call + 1)[0]) & 0xffffffff != ctor:
        call = body.index(b'\xe8', call + 1)
main_obj, main_flags = build('NativeAppUnit634_2008_value', SRC)

